  const card = article => { const c = currentCopy(); return `<article class="blog-card"><img class="blog-card-image-editorial" src="${article.hero_image}" alt="${esc(article.image_alt)}" width="${article.width}" height="${article.height}" loading="lazy"><div class="blog-card-body"><p class="blog-category">${esc(article.categoryLabel)}</p><h3>${esc(article.title)}</h3><p>${esc(article.description)}</p><p class="blog-meta">${esc(article.author)} · ${article.minutes} ${esc(c.readTime)} · ${article.date}</p><a class="blog-link" href="${articleUrl(article)}">${esc(c.read)} <span aria-hidden="true">→</span></a></div></article>`; };
  const sectionMarkup = section => `<section><h2>${esc(section.heading)}</h2>${(section.paragraphs || []).map(paragraph => `<p>${esc(paragraph)}</p>`).join("")}${section.checklist ? `<ul>${section.checklist.map(item => `<li>${esc(item)}</li>`).join("")}</ul>` : ""}</section>`;
  const shell = (title, text, content) => `${nav()}<header class="blog-hero"><div class="blog-hero-inner"><p class="public-kicker">Total Solutions Cancún</p><h1>${esc(title)}</h1><p>${esc(text)}</p></div></header><main class="blog-content">${content}</main>${footer()}`;
