  const renderIndex = () => { const c = currentCopy(); const articles = meta.map((_, index) => localizedArticle(index)); const title = "Blog"; const description = lang === "en" ? "Practical ideas about professional maintenance for properties, hotels, Airbnb and investments in Cancún." : lang === "pt-BR" ? "Ideias práticas sobre manutenção profissional para imóveis, hotéis, Airbnb e investimentos em Cancún." : "Ideas prácticas sobre mantenimiento profesional para propiedades, hoteles, Airbnb e inversiones en Cancún."; document.title = `${title} | Total Solutions Cancún`; setMeta('meta[name="description"]', description); setSchema({ "@context": "https://schema.org", "@type": "CollectionPage", name: title, description, url: "https://totalsolutionscancun.com/blog", inLanguage: lang, mainEntity: articles.map(article => ({ "@type": "Article", headline: article.title, url: `https://totalsolutionscancun.com${articleUrl(article)}`, image: [`https://totalsolutionscancun.com${article.hero_image}`], author: { "@type": "Organization", name: article.author }, datePublished: article.date })) }); const filters = ["all", ...new Set(meta.map(article => article.category))]; document.body.innerHTML = shell(title, c.intro, `<div class="blog-toolbar"><div><h2>${esc(c.context)}</h2></div><p>${esc(c.toolbar)}</p></div><div class="blog-filters" role="group" aria-label="${esc(c.context)}">${filters.map((filter, index) => `<button type="button" class="blog-filter" data-filter="${filter}" aria-pressed="${index === 0}">${esc(filter === "all" ? c.all : c.categories[filter])}</button>`).join("")}</div><div class="blog-grid">${articles.map(card).join("")}</div>`); bindNav(); document.querySelectorAll(".blog-filter").forEach(button => button.addEventListener("click", () => { const filter = button.dataset.filter; document.querySelectorAll(".blog-filter").forEach(item => item.setAttribute("aria-pressed", String(item === button))); document.querySelectorAll(".blog-card").forEach((item, index) => { item.hidden = filter !== "all" && meta[index].category !== filter; }); })); };
  const renderPost = index => { const c = currentCopy(); const article = localizedArticle(index); const url = `https://totalsolutionscancun.com${articleUrl(article)}`; const whatsappUrl = `https://wa.me/529984078199?text=${encodeURIComponent(article.whatsappMessage)}`; document.title = `${article.title} | Total Solutions Cancún`; updateDocumentLanguage(); setMeta('meta[name="description"]', article.description); document.querySelector('link[rel="canonical"]').href = url; setMeta('meta[property="og:title"]', article.title); setMeta('meta[property="og:description"]', article.description); setMeta('meta[property="og:url"]', url); setMeta('meta[property="og:image"]', `https://totalsolutionscancun.com${article.hero_image}`); setSchema({ "@context": "https://schema.org", "@type": "Article", headline: article.title, description: article.description, image: [`https://totalsolutionscancun.com${article.hero_image}`], inLanguage: lang, author: { "@type": "Organization", name: article.author }, publisher: { "@type": "Organization", name: "Total Solutions Cancún", logo: { "@type": "ImageObject", url: "https://totalsolutionscancun.com/assets/assets/total-solutions-logo.svg" } }, datePublished: article.date, dateModified: article.date, mainEntityOfPage: { "@type": "WebPage", "@id": url } }); const secondaryCta = article.ctaSecondaryLabel ? `<a href="${article.ctaSecondaryUrl}">${esc(article.ctaSecondaryLabel)}</a>` : ""; const body = `<a class="blog-back" href="/blog">${esc(c.back)}</a><article class="blog-article"><p class="blog-category">${esc(article.categoryLabel)}</p><h1>${esc(article.title)}</h1><p class="blog-dek">${esc(article.description)}</p><p class="blog-meta">${esc(article.author)} · ${article.minutes} ${esc(c.readTime)} · ${article.date}</p><figure><img class="blog-card-image-editorial" src="${article.hero_image}" alt="${esc(article.image_alt)}" width="${article.width}" height="${article.height}" loading="eager"><figcaption>Total Solutions Cancún · ${esc(c.footer)}</figcaption></figure>${article.sections.map(sectionMarkup).join("")}<div class="public-callout"><div><h2>${esc(article.ctaTitle)}</h2><p>${esc(article.ctaText)}</p></div><a href="/solicitar-servico">${esc(article.ctaLabel)}</a>${secondaryCta}<a href="${whatsappUrl}" target="_blank" rel="noopener">${esc(c.whatsapp)}</a></div></article><section class="blog-related"><h2>${esc(c.related)}</h2><div class="blog-grid">${meta.map((_, relatedIndex) => relatedIndex).filter(relatedIndex => relatedIndex !== index).map(relatedIndex => card(localizedArticle(relatedIndex))).join("")}</div></section>`; document.body.innerHTML = shell(article.title, article.description, body); bindNav(); };
