  const render = () => { if (document.body.dataset.blogPage === "post" && index >= 0) renderPost(index); else if (document.body.dataset.blogPage === "post") renderNotFound(); else renderIndex(); };
  const slug = decodeURIComponent(location.pathname.replace(/^\/blog\/?/, "").replace(/\/$/, ""));
  const index = meta.findIndex(article => article.slug === slug);
